class HidRuntimeTests{[STAThread]static int Main(){Environment.SetEnvironmentVariable("ROCKTEK_REMOTE_DEVICE","AABBCCDDEEFF");var t=typeof(RemoteConfig).Assembly.GetType("RockTekRemote");var f=BindingFlags.Instance|BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public;var obj=FormatterServices.GetUninitializedObject(t);Action<string,object> set=(n,v)=>t.GetField(n,f).SetValue(obj,v);var fake=new HidFake();var cfg=RemoteConfig.Defaults();var b=new ButtonConfig{InputType="Consumer",Usage=0x9c,Action="Key",Key="VolumeUp",Scope="Global",Repeat=false};cfg.Buttons["CH+"]=b;set("Config",cfg);set("ConfigPath",Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"fixture.json"));set("Clock",Stopwatch.StartNew());set("Repeater",new HoldRepeater());set("ActionAdapter",fake);set("HomeLock",new object());set("PendingHomes",new List<long>());set("HookLogs",new System.Collections.Concurrent.ConcurrentQueue<string>());set("RemoteHomeTick",(long)-10000);set("WakeHome",new WakeHomeRouter());set("LogFile",Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"hid-fixture.log"));using(var r=new HidConsumerReader(false)){set("DirectConsumer",r);string dev="hid#AABBCCDDEEFF&col02#fixture";r.Offer(dev,new byte[]{2,0x9c,0,0,0});r.Offer(dev,new byte[]{2,0,0,0,0});t.GetMethod("Tick",f).Invoke(obj,null);var ex=(ActionExecutor)t.GetField("Executor",f).GetValue(obj);ex.WaitForIdle(1000);if(fake.Keys!=1||fake.Last!="VolumeUp")throw new Exception("FAIL direct HID must execute saved global volume without WM_INPUT");if((ushort)t.GetField("LastUsage",f).GetValue(obj)!=0)throw new Exception("FAIL direct release must clear held usage");Console.WriteLine("PASS direct HID queue to native Tick to saved VolumeUp action; release clears hold");b.Action="Native";r.Offer(dev,new byte[]{2,0x9c,0,0,0});r.Offer(dev,new byte[]{2,0,0,0,0});t.GetMethod("Tick",f).Invoke(obj,null);if(fake.Keys!=1)throw new Exception("FAIL Native duplicated");Console.WriteLine("PASS Native action remains passthrough without injection");cfg.Buttons["Home"].Action="Key";cfg.Buttons["Home"].Key="Enter";cfg.Buttons["Home"].Scope="Global";r.Offer(dev,new byte[]{2,0x23,2,0,0});r.Offer(dev,new byte[]{2,0,0,0,0});t.GetMethod("Tick",f).Invoke(obj,null);ex.WaitForIdle(1000);if(fake.Keys!=1)throw new Exception("FAIL direct Home must defer activation until wake transition settles");System.Threading.Thread.Sleep(250);t.GetMethod("Tick",f).Invoke(obj,null);ex.WaitForIdle(1000);if(fake.Keys!=2||fake.Last!="Enter"||(ushort)t.GetField("LastUsage",f).GetValue(obj)!=0)throw new Exception("FAIL deferred Home action exactly once and no stuck hold");Console.WriteLine("PASS direct Home delayed until wake settles; one action and cleared hold");ex.Dispose();}return 0;}}
